head.b:skin:
/* ------------------------------------------------------------
   AMS Light tokens. Only place colours / radii / widths are set.
   Colours are contrast-checked on light surfaces: never lighten
   --ink-2 past #3D4757 or --accent past #0050BC.
   ------------------------------------------------------------ */
:root{
  color-scheme:light;
  --bg:#F6F8FC; --surface:#FFFFFF; --surface-2:#EDF2FA;
  --ink:#0B1220; --ink-2:#3D4757; --ink-3:#5A6577;
  --line:#E2E8F2; --line-2:#CFDAEA;
  --brand-1:#409CFF; --brand-2:#005CD6; --accent:#0050BC; --accent-2:#003E99;
  --tint:#E8F1FF;
  --grad:linear-gradient(90deg,#0B63D6,#0047B3);
  --grad-red:linear-gradient(90deg,#C42B25,#8E1414);
  --r:14px; --r-s:10px; --r-l:22px;
  --sh:0 1px 2px rgba(11,18,32,.05),0 14px 34px -22px rgba(11,18,32,.28);
  --sh-2:0 1px 2px rgba(11,18,32,.06),0 6px 16px -10px rgba(11,18,32,.16);
  --wrap:1080px; --read:720px; --rail:296px;
  --font:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,'Noto Sans',sans-serif;
  --mono:ui-monospace,SFMono-Regular,'SF Mono',Menlo,Consolas,'Liberation Mono',monospace;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{
  margin:0;background:var(--bg);color:var(--ink);
  font-family:var(--font);font-size:17px;line-height:1.65;
  -webkit-font-smoothing:antialiased;
}
/* Blogger's own widget/section wrappers must not interfere with our flex layout */
.section,.sec,.widget,.widget-content{display:contents}
img,svg{max-width:100%;height:auto}
img{border-style:none}
h1,h2,h3,h4{margin:0;line-height:1.18;letter-spacing:-.02em;text-wrap:balance}
p{margin:0 0 1.05em}
a{color:var(--accent);text-decoration:none}
a:hover{color:var(--accent-2);text-decoration:underline;text-underline-offset:2px}
:focus-visible{outline:2px solid var(--brand-2);outline-offset:2px;border-radius:4px}
::selection{background:var(--tint);color:var(--ink)}
.wrap{width:100%;max-width:var(--wrap);margin:0 auto;padding:0 20px}
.vh{position:absolute!important;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.skip{
  position:absolute;left:12px;top:-64px;z-index:40;padding:11px 16px;border-radius:var(--r-s);
  background:var(--surface);box-shadow:var(--sh);color:var(--ink);font-weight:700;font-size:14px;
}
.skip:focus{top:12px;color:var(--accent)}

/* ---------------- header + tab bar ---------------- */
.hdr{position:sticky;top:0;z-index:30;background:var(--surface);border-bottom:1px solid var(--line)}
.hdr::after{content:'';display:block;height:2px;background:linear-gradient(90deg,var(--brand-1),var(--brand-2) 46%,rgba(0,92,214,0))}
.hdr-in{display:flex;align-items:stretch;min-height:62px}
.brand{display:inline-flex;align-items:center;gap:11px;flex:0 0 auto;color:var(--ink);text-decoration:none}
.brand:hover{color:var(--ink);text-decoration:none}
.mark{display:block;flex:0 0 auto;border-radius:9px}
.brand-tx{display:flex;flex-direction:column;min-width:0;line-height:1.12}
.brand-name{margin:0;font-size:20px;font-weight:800;letter-spacing:.16em;line-height:1.1}
.brand-tag{font-size:13px;font-weight:500;letter-spacing:.01em;color:var(--ink-2)}
.brand:hover .brand-name{color:var(--accent)}
.tabs{display:flex;align-items:stretch;flex:1 1 auto;min-width:0;margin-left:auto}
.tablist{display:flex;align-items:stretch;gap:2px;list-style:none;margin:0;padding:0}
.tablist li{display:flex}
.tab{
  display:inline-flex;align-items:center;gap:7px;height:100%;min-height:44px;padding:0 15px;
  border-bottom:2px solid transparent;color:var(--ink-2);
  font-size:14px;font-weight:600;letter-spacing:.02em;white-space:nowrap;
  transition:color .16s,background-color .16s,border-color .16s;
}
.tab:hover{color:var(--accent);background:var(--surface-2);border-bottom-color:var(--line-2);text-decoration:none}
.tab.on{color:var(--accent);border-bottom-color:var(--brand-2);background:linear-gradient(180deg,rgba(232,241,255,0),var(--tint))}
.tab.yt{align-self:center;height:auto;min-height:38px;margin-left:6px;padding:0 15px;border-bottom:0;
  border-radius:999px;background:var(--grad-red);color:#fff;font-weight:700}
.tab.yt:hover{background:var(--grad-red);filter:brightness(1.1);color:#fff}

/* ---------------- hero / band ---------------- */
.band{background:linear-gradient(180deg,#EAF2FF,#F8FAFE 68%);border-bottom:1px solid var(--line);padding:clamp(26px,5vw,52px) 0 clamp(24px,4.4vw,44px)}
.band.is-flat{background:var(--surface);padding:clamp(20px,3.2vw,30px) 0}
.band-in{max-width:860px}
.kicker{
  display:inline-flex;align-items:center;gap:9px;margin:0 0 14px;padding:6px 14px 6px 8px;
  border:1px solid var(--line-2);border-radius:999px;background:rgba(255,255,255,.8);
  font-size:13px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-2);
}
.kicker i{display:inline-block;width:22px;height:22px;flex:0 0 auto;border-radius:7px;background:var(--grad)}
.band-t{font-size:clamp(30px,5.2vw,50px);font-weight:800;letter-spacing:-.035em}
.band.is-flat .band-t{font-size:clamp(24px,3.6vw,34px)}
.band-s{margin:14px 0 0;max-width:58ch;font-size:clamp(16px,2vw,19px);color:var(--ink-2);text-wrap:pretty}
.band-cta{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0 0}

/* ---------------- buttons ---------------- */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:9px;
  min-height:46px;padding:11px 22px;border:1px solid transparent;border-radius:999px;
  background:var(--surface);color:var(--ink);font-size:15px;font-weight:700;line-height:1;white-space:nowrap;
  transition:transform .14s,box-shadow .16s,filter .16s;
}
.btn:hover{text-decoration:none;transform:translateY(-1px)}
.btn:active{transform:translateY(0)}
.btn-primary{background:var(--grad);color:#fff;box-shadow:inset 0 1px 0 rgba(255,255,255,.26),var(--sh-2)}
.btn-primary:hover{color:#fff}
.btn-red{background:var(--grad-red);color:#fff}
.btn-red:hover{color:#fff;filter:brightness(1.08)}
.btn-ghost{border-color:var(--line-2);color:var(--accent)}
.btn-ghost:hover{border-color:var(--brand-2);background:var(--surface);color:var(--accent-2)}
.post-body .btn{color:#fff;text-decoration:none}

/* ---------------- columns ---------------- */
.cols{display:flex;align-items:flex-start;gap:34px;padding:clamp(22px,3.2vw,36px) 0 8px}
.col{flex:1 1 auto;min-width:0;max-width:var(--read)}
.rail{flex:0 0 var(--rail);width:var(--rail)}

/* ---------------- feed cards ---------------- */
.feed{display:flex;flex-direction:column;gap:16px}
.card{
  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);
  padding:24px 26px;box-shadow:var(--sh-2);
  transition:box-shadow .18s,border-color .18s;
}
.card:hover{border-color:var(--line-2);box-shadow:var(--sh)}
.card-t{font-size:clamp(21px,2.4vw,26px);font-weight:700;letter-spacing:-.022em}
.card-t a{color:var(--ink)}
.card-t a:hover{color:var(--accent);text-decoration:none}
.meta{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin:10px 0 0;font-size:13px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-2)}
.meta .who{color:var(--accent)}
.meta .dot{width:4px;height:4px;border-radius:50%;background:var(--line-2)}
.excerpt{margin:12px 0 0;color:var(--ink-2);font-size:16px;text-wrap:pretty}
.more{display:inline-flex;align-items:center;gap:7px;margin-top:16px;font-size:15px;font-weight:700;min-height:32px}
.more::after{content:'\2192';transition:transform .16s ease-out}
.more:hover::after{transform:translateX(3px)}

/* ---------------- article ---------------- */
.post{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-l);padding:clamp(22px,3.6vw,42px);box-shadow:var(--sh);margin:0 0 24px}
.post-t{font-size:clamp(28px,4.6vw,42px);font-weight:800;letter-spacing:-.03em}
.post-body{margin-top:22px;font-size:17.5px;line-height:1.72;color:var(--ink)}
.post-body>*:last-child{margin-bottom:0}
.post-body h2{margin:1.8em 0 .5em;font-size:clamp(22px,2.8vw,28px);font-weight:700;letter-spacing:-.024em}
.post-body h3{margin:1.5em 0 .45em;font-size:clamp(18px,2.2vw,21px);font-weight:700}
.post-body h2,.post-body h3,.post-body h4{scroll-margin-top:84px}
.post-body a{font-weight:600;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:2px}
.post-body ul,.post-body ol{margin:0 0 1.1em;padding-left:22px}
.post-body li{margin:7px 0}
.post-body li::marker{color:var(--brand-2)}
.post-body strong{font-weight:700}
.post-body img{margin:20px 0;border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh-2)}
.post-body hr{margin:30px 0;border:0;border-top:1px solid var(--line)}
.post-body blockquote{
  margin:26px 0;padding:16px 22px;border-left:3px solid var(--brand-2);
  background:var(--surface-2);border-radius:0 var(--r) var(--r) 0;color:var(--ink-2);
}
.post-body blockquote p:last-child{margin-bottom:0}
.post-body code,.post-body pre{font-family:var(--mono);font-size:.9em}
.post-body code{padding:.12em .4em;background:var(--surface-2);border:1px solid var(--line);border-radius:6px}
.post-body pre{margin:22px 0;padding:16px 18px;border-radius:var(--r);background:#0B1220;color:#EEF3FA;overflow:auto;line-height:1.6}
.post-body pre code{padding:0;background:none;border:0;color:inherit}
.post-body table{width:100%;margin:20px 0;border-collapse:collapse;font-size:16px}
.post-body th,.post-body td{padding:9px 12px;border:1px solid var(--line);text-align:left}
.post-body th{background:var(--surface-2);font-size:14px;letter-spacing:.03em;text-transform:uppercase}
.post-body figure{margin:20px 0}
.post-body figcaption{margin-top:8px;font-size:14px;color:var(--ink-2);text-align:center}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:24px;padding-top:22px;border-top:1px solid var(--line)}
.card .chips{margin-top:16px;padding-top:0;border-top:0}
.chip{
  display:inline-flex;align-items:center;min-height:34px;padding:6px 14px;border-radius:999px;
  background:var(--surface-2);border:1px solid var(--line);color:var(--accent);
  font-size:13.5px;font-weight:700;letter-spacing:.02em;
}
.chip:hover{background:var(--tint);border-color:var(--brand-1);color:var(--accent-2);text-decoration:none}

/* ---------------- rail ---------------- */
.wg{margin:0 0 16px;padding:20px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh-2)}
.wg-t{margin:0 0 12px;font-size:13px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-2)}
.wg ul{list-style:none;margin:0;padding:0}
.wg li+li{border-top:1px solid var(--line)}
.wg li a{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:40px;font-size:15px;color:var(--ink)}
.wg li a:hover{color:var(--accent);text-decoration:none}
.wg .n{padding:2px 9px;border-radius:999px;background:var(--surface-2);font-size:13px;font-weight:700;color:var(--ink-2)}
.wg-about{background:linear-gradient(180deg,#0B1220,#132442);border-color:#0B1220;color:#EEF3FA}
.wg-about .wg-t{color:#9ECBFF}
.wg-about p{margin-bottom:16px;font-size:15px;line-height:1.6;color:#DCE6F5}
.wg-about .btn{width:100%}
.search{display:flex;gap:8px}
.search input{
  flex:1 1 auto;min-width:0;min-height:44px;padding:10px 14px;
  font:inherit;font-size:15px;color:var(--ink);
  background:var(--surface-2);border:1px solid var(--line-2);border-radius:var(--r-s);
}
.search input::placeholder{color:var(--ink-3)}
.search input:focus{background:var(--surface);border-color:var(--brand-2);outline:none;box-shadow:0 0 0 3px rgba(0,92,214,.16)}
.search button{
  flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;width:48px;min-height:44px;
  border:0;border-radius:var(--r-s);background:var(--grad);color:#fff;cursor:pointer;box-shadow:var(--sh-2);
}
.search button:hover{filter:brightness(1.08)}

/* ---------------- pager ---------------- */
.pager{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin:24px 0 4px}
.pager a{
  display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:10px 18px;
  border:1px solid var(--line-2);border-radius:999px;background:var(--surface);
  color:var(--ink);font-size:14.5px;font-weight:700;
}
.pager a:hover{border-color:var(--brand-2);color:var(--accent);text-decoration:none}

/* ---------------- footer ---------------- */
.ftr{margin-top:clamp(26px,4vw,44px);background:var(--surface);border-top:1px solid var(--line)}
.ftr-in{display:flex;flex-wrap:wrap;gap:12px 24px;align-items:center;padding:24px 0}
.ftr-b{display:inline-flex;align-items:center;gap:10px;font-size:15px;font-weight:800;letter-spacing:.16em;color:var(--ink)}
.ftr-l{display:flex;flex-wrap:wrap;gap:4px 18px;list-style:none;margin:0 0 0 auto;padding:0}
.ftr-l a{display:inline-flex;align-items:center;min-height:32px;font-size:14px;font-weight:600;color:var(--ink-2)}
.ftr-l a:hover{color:var(--accent)}
.ftr-note{width:100%;margin:6px 0 0;padding-top:16px;border-top:1px solid var(--line);font-size:13.5px;color:var(--ink-2)}

/* ---------------- responsive ---------------- */
@media (max-width:1000px){
  .cols{flex-direction:column;gap:24px}
  .col,.rail{flex:1 1 auto;width:100%;max-width:var(--read)}
}
@media (max-width:899px){
  .brand-tag{display:none}
}
@media (max-width:640px){
  body{font-size:16.5px}
  .hdr{position:static}
  .hdr-in{flex-direction:column;align-items:stretch;min-height:0;padding:10px 0 0}
  .brand{padding:0 0 10px}
  .tabs{margin:0 -20px;padding:0 20px;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
  .tabs::-webkit-scrollbar{display:none}
  .tab{height:auto;min-height:48px;scroll-snap-align:center}
  .tab.yt{margin:8px 0;border-radius:999px;padding:0 16px}
  .card,.post{border-radius:var(--r);padding:20px 18px}
  .post-body{font-size:16.5px}
  .band-cta .btn{flex:1 1 auto}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.001ms!important;transition-duration:.001ms!important}
}
@media print{
  .hdr,.rail,.ftr,.band-cta,.pager,.skip,.chips{display:none}
  body{background:#fff;color:#000}
  .post{padding:0;border:0;box-shadow:none}
}
